package fraymus.workspace;

import org.json.*;
import java.io.*;
import java.net.URI;
import java.nio.*;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;

/** Durable object associations and read-only research. Never writes the native world. */
final class KnowledgeStore {
    static final String VERSION="object-knowledge-039-v1";
    private final Path root,stateFile;
    private final TabletopStore tabletop;
    private final boolean fixtures;
    interface Transaction<T>{T apply(JSONObject state)throws Exception;}

    KnowledgeStore(Path project,TabletopStore tabletop)throws Exception{this(project,tabletop,"1".equals(System.getenv("FRAYNIX_WORKSPACE_TEST")));}
    KnowledgeStore(Path project,TabletopStore tabletop,boolean fixtures)throws Exception{
        this.tabletop=tabletop;this.fixtures=fixtures;root=project.resolve("knowledge-039");stateFile=root.resolve("state.json");
        access(true,s->{for(Object raw:s.getJSONArray("jobs")){var j=(JSONObject)raw;if(j.getString("status").equals("running")){j.put("status","interrupted").put("reason","Process ended; completed source receipts retained. Resume explicitly.");j.remove("lease");}}return null;});
    }
    private synchronized <T>T access(boolean write,Transaction<T> tx)throws Exception{
        Files.createDirectories(root);
        try(var channel=FileChannel.open(root.resolve("state.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);var lock=channel.lock()){
            JSONObject s;
            if(Files.exists(stateFile)){if(Files.size(stateFile)>4_000_000)throw new IOException("Knowledge journal capacity exceeded; preserve originals");var e=new JSONObject(Files.readString(stateFile));s=e.getJSONObject("payload");if(!VERSION.equals(e.getString("schema"))||!WorldFrames.hash(s).equals(e.getString("sha256")))throw new IOException("Knowledge journal checksum differs; originals preserved");}
            else s=new JSONObject().put("objects",new JSONArray()).put("jobs",new JSONArray());
            T value=tx.apply(s);
            if(write){if(s.getJSONArray("objects").length()>64||s.getJSONArray("jobs").length()>64)throw new IllegalStateException("Knowledge budget reached; no history pruned");byte[] bytes=new JSONObject().put("schema",VERSION).put("sha256",WorldFrames.hash(s)).put("payload",s).toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>4_000_000)throw new IllegalStateException("Knowledge metadata exceeds4MB");Path pending=root.resolve("state.pending.json");try(var out=FileChannel.open(pending,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){var b=ByteBuffer.wrap(bytes);while(b.hasRemaining())out.write(b);out.force(true);}Files.move(pending,stateFile,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
            return value;
        }
    }
    private static JSONObject find(JSONArray a,String id){for(Object raw:a){var o=(JSONObject)raw;if(o.getString("id").equals(id))return o;}throw new IllegalArgumentException("Unknown durable knowledge identity");}
    private static String text(JSONObject in,String key,int max){String v=in.getString(key).strip();if(v.isBlank()||v.length()>max)throw new IllegalArgumentException(key+" needs1.."+max+" characters");return v;}
    static String url(String value){if(value.length()>2048)throw new IllegalArgumentException("Source URL too long");var u=URI.create(value);if(!Set.of("http","https").contains(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getFragment()!=null)throw new IllegalArgumentException("Use an absolute HTTP(S) source without credentials/fragment");return u.toASCIIString();}
    static boolean loopback(String value){String h=URI.create(value).getHost();return Set.of("localhost","127.0.0.1","[::1]","::1").contains(h);}
    static JSONObject summary(JSONObject object){var out=WorldFrames.copy(object);out.remove("bindings");out.put("bindingCount",object.getJSONArray("bindings").length());return out;}
    JSONObject state()throws Exception{return access(false,s->{var a=new JSONArray();for(Object raw:s.getJSONArray("objects"))a.put(summary((JSONObject)raw));var jobs=new JSONArray();for(Object raw:s.getJSONArray("jobs"))jobs.put(jobSummary((JSONObject)raw));return new JSONObject().put("schema",VERSION).put("selectedObjectId",s.optString("selectedObjectId","")).put("objects",a).put("jobs",jobs);});}
    JSONObject select(String id)throws Exception{return access(true,s->{var o=find(s.getJSONArray("objects"),id);s.put("selectedObjectId",id);return summary(o);});}
    JSONObject bind(JSONObject input)throws Exception{
        SpatialScene.keys(input,"runId","objectId","label","category");String label=text(input,"label",100),category=text(input,"category",100);var run=tabletop.read(input.getString("runId"));if(run.getInt("completedFrames")==0)throw new IllegalArgumentException("Bind an actual recorded observation first");
        var facts=tabletop.understanding(run.getString("id"));var evidence=new JSONObject().put("runId",run.getString("id")).put("bodyId",run.getString("bodyId")).put("worldId",run.getJSONObject("nativeBinding").getString("worldId")).put("codeSha256",run.getString("codeSha256")).put("geometrySha256",facts.getString("geometrySha256")).put("ordinal",run.getInt("completedFrames")).put("imageSha256",facts.getJSONObject("latest").getJSONObject("frame").getString("imageSha256")).put("boundAt",Instant.now()).put("scope",run.getString("labelSource")+"; "+run.getJSONObject("check").getString("source"));
        return access(true,s->{JSONObject object=null;if(input.has("objectId")&&!input.getString("objectId").isBlank())object=find(s.getJSONArray("objects"),input.getString("objectId"));else for(Object raw:s.getJSONArray("objects")){var o=(JSONObject)raw;for(Object binding:o.getJSONArray("bindings"))if(((JSONObject)binding).getString("runId").equals(run.getString("id")))object=o;}
            if(object==null){object=new JSONObject().put("id",UUID.randomUUID().toString()).put("identityRevision",1).put("createdAt",Instant.now()).put("nativeAssociation",new JSONObject().put("worldId",evidence.getString("worldId")).put("bodyId",evidence.getString("bodyId"))).put("bindings",new JSONArray());s.getJSONArray("objects").put(object);}
            var assoc=object.getJSONObject("nativeAssociation");if(!assoc.getString("worldId").equals(evidence.getString("worldId"))||!assoc.getString("bodyId").equals(evidence.getString("bodyId")))throw new IllegalArgumentException("Explicit object association requires the same durable world/body; cross-world identity is not inferred");
            if(object.has("label")&&(!object.getString("label").equals(label)||!object.getString("category").equals(category)))object.put("identityRevision",object.getInt("identityRevision")+1);
            object.put("label",label).put("category",category).put("labelSource","Human guidance; no automatic semantic identification").put("updatedAt",Instant.now());var bindings=object.getJSONArray("bindings");boolean replaced=false;for(int i=0;i<bindings.length();i++)if(bindings.getJSONObject(i).getString("runId").equals(evidence.getString("runId"))){bindings.put(i,evidence);replaced=true;break;}if(!replaced){if(bindings.length()>=32)throw new IllegalStateException("Object observation budget reached; originals retained");bindings.put(evidence);}return WorldFrames.copy(object);
        });
    }
    JSONObject object(String id)throws Exception{
        var object=access(false,s->WorldFrames.copy(find(s.getJSONArray("objects"),id)));var bindings=object.getJSONArray("bindings");object.put("currentObservation",tabletop.understanding(bindings.getJSONObject(bindings.length()-1).getString("runId")));
        var jobs=access(false,s->{var a=new JSONArray();for(Object raw:s.getJSONArray("jobs")){var j=(JSONObject)raw;if(j.getString("objectId").equals(id))a.put(jobSummary(j));}return a;});return object.put("research",jobs).put("limits","Physical identity is human-associated. Web references are untrusted candidate knowledge, not visual matches, measured material properties or permission to act.");
    }
    JSONObject start(JSONObject input)throws Exception{
        SpatialScene.keys(input,"objectId","urls","fixtureOrigin");String objectId=input.getString("objectId");return access(true,s->{var object=find(s.getJSONArray("objects"),objectId);for(Object raw:s.getJSONArray("jobs")){var prior=(JSONObject)raw;if(prior.getString("objectId").equals(objectId)&&Set.of("queued","running","interrupted").contains(prior.getString("status")))throw new IllegalStateException("This object already owns unfinished research; Read, Resume or Cancel it");}
            String query=object.getString("category")+" identification reference images";var search=new JSONArray();var pages=new JSONArray();String kind="web",mode="search";
            if(input.has("fixtureOrigin")){if(!fixtures)throw new IllegalArgumentException("Controlled fixtures are unavailable in production");String origin=url(input.getString("fixtureOrigin"));if(!loopback(origin))throw new IllegalArgumentException("Fixture source must be loopback");kind="controlled-fixture";search.put(origin+"/search?q="+java.net.URLEncoder.encode(query,StandardCharsets.UTF_8)).put(origin+"/search2?q="+java.net.URLEncoder.encode(query,StandardCharsets.UTF_8));}
            else search.put("https://www.google.com/search?q="+java.net.URLEncoder.encode(query,StandardCharsets.UTF_8)).put("https://www.bing.com/search?q="+java.net.URLEncoder.encode(query,StandardCharsets.UTF_8));
            if(input.has("urls")){mode="provided-urls";search=new JSONArray();var urls=input.getJSONArray("urls");if(urls.isEmpty()||urls.length()>3)throw new IllegalArgumentException("Provide1..3 source URLs");for(Object raw:urls){String u=url(raw.toString());if(loopback(u)){if(!fixtures)throw new IllegalArgumentException("Local sources require controlled test mode");kind="controlled-fixture";}if(!pages.toList().contains(u))pages.put(u);}}
            var job=new JSONObject().put("id",UUID.randomUUID().toString()).put("objectId",objectId).put("identityRevision",object.getInt("identityRevision")).put("category",object.getString("category")).put("query",query).put("mode",mode).put("sourceKind",kind).put("searchPlan",search).put("pagePlan",pages).put("steps",new JSONArray()).put("sources",new JSONArray()).put("searchAttempts",0).put("pageAttempts",0).put("status","queued").put("generation",0).put("attempts",0).put("createdAt",Instant.now()).put("reason","Queued for the separate browser worker; no private camera images sent");s.getJSONArray("jobs").put(job);return jobSummary(job);
        });
    }
    static JSONObject jobSummary(JSONObject j){var out=WorldFrames.copy(j);out.remove("lease");out.remove("searchPlan");out.remove("pagePlan");return out;}
    JSONObject job(String id)throws Exception{return access(false,s->jobSummary(find(s.getJSONArray("jobs"),id)));}
    void hostDetached044()throws Exception{access(true,s->{for(Object raw:s.getJSONArray("jobs")){var j=(JSONObject)raw;if(j.getString("status").equals("running")){j.put("status","interrupted").put("generation",j.getInt("generation")+1).put("reason","Interface browser ended; completed source receipts retained. Resume explicitly.");j.remove("lease");}}return null;});}
    JSONObject claim()throws Exception{return access(true,s->{for(Object raw:s.getJSONArray("jobs"))if(((JSONObject)raw).getString("status").equals("running"))return new JSONObject().put("idle",true);for(Object raw:s.getJSONArray("jobs")){var j=(JSONObject)raw;if(j.getString("status").equals("queued")){j.put("status","running").put("generation",j.getInt("generation")+1).put("attempts",j.getInt("attempts")+1).put("lease",UUID.randomUUID().toString()).put("attemptStartedAt",Instant.now()).put("reason","Separate browser worker is reading bounded public evidence");return WorldFrames.copy(j);}}return new JSONObject().put("idle",true);});}
    private static void own(JSONObject j,JSONObject input){if(!j.getString("status").equals("running")||j.getInt("generation")!=input.getInt("generation")||!j.getString("lease").equals(input.getString("lease")))throw new IllegalStateException("Research stopped or lease is stale");}
    JSONObject work(JSONObject input)throws Exception{return access(false,s->{var j=find(s.getJSONArray("jobs"),input.getString("id"));own(j,input);if(java.time.Duration.between(Instant.parse(j.getString("attemptStartedAt")),Instant.now()).toSeconds()>120)throw new IllegalStateException("Research attempt exceeds120seconds; interrupt and preserve progress");var pages=j.getJSONArray("pagePlan");int n=j.getInt("pageAttempts");if(n<pages.length())return new JSONObject().put("phase","source").put("url",pages.getString(n)).put("index",n).put("sourceKind",j.getString("sourceKind"));var search=j.getJSONArray("searchPlan");int attempt=j.getInt("searchAttempts");if(pages.isEmpty()&&attempt<search.length())return new JSONObject().put("phase","search").put("url",search.getString(attempt)).put("index",attempt).put("sourceKind",j.getString("sourceKind"));return new JSONObject().put("done",true);});}
    private JSONObject cache(JSONObject document)throws Exception{
        String hash=WorldFrames.hash(document);Path folder=root.resolve("sources");Files.createDirectories(folder);Path p=folder.resolve(hash+".json");if(!Files.exists(p)){try(var files=Files.list(folder)){if(files.count()>=256)throw new IllegalStateException("Source cache budget reached; no pruning");}Files.writeString(p,document.toString(),StandardOpenOption.CREATE_NEW);}else if(!WorldFrames.hash(new JSONObject(Files.readString(p))).equals(hash))throw new IOException("Original source cache differs");return new JSONObject().put("sha256",hash).put("url",document.getString("url")).put("finalUrl",document.getString("finalUrl")).put("title",document.getString("title")).put("textSha256",document.getString("textSha256")).put("observedAt",document.getString("observedAt")).put("imageReferences",document.getJSONArray("images").length());
    }
    JSONObject source(String hash)throws Exception{if(!hash.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Invalid source hash");Path p=root.resolve("sources").resolve(hash+".json");if(Files.size(p)>100_000)throw new IOException("Source exceeds cache budget");var d=new JSONObject(Files.readString(p));if(!WorldFrames.hash(d).equals(hash)||!MeasurementStore.hash(d.getString("text")).equals(d.getString("textSha256")))throw new IOException("Cached source checksum differs; original preserved");return d;}
    JSONObject acknowledge(JSONObject input)throws Exception{
        SpatialScene.keys(input,"id","generation","lease","phase","index","url","ok","reason","document","links");
        return access(true,s->{var j=find(s.getJSONArray("jobs"),input.getString("id"));own(j,input);String phase=input.getString("phase");if(!Set.of("search","source").contains(phase))throw new IllegalArgumentException("Unknown research phase");String counter=phase.equals("search")?"searchAttempts":"pageAttempts",plan=phase.equals("search")?"searchPlan":"pagePlan";int index=input.getInt("index");if(index!=j.getInt(counter)||index>=j.getJSONArray(plan).length()||!j.getJSONArray(plan).getString(index).equals(input.getString("url")))throw new IllegalStateException("Research source/index differs from frozen work");
            var step=new JSONObject().put("phase",phase).put("index",index).put("url",input.getString("url")).put("ok",input.getBoolean("ok")).put("at",Instant.now());if(input.has("reason"))step.put("reason",input.getString("reason").substring(0,Math.min(600,input.getString("reason").length())));
            if(input.getBoolean("ok")&&!input.has("document"))throw new IllegalArgumentException("Successful work requires its actual source document");
            if(input.has("document")){var d=input.getJSONObject("document");SpatialScene.keys(d,"url","finalUrl","title","text","images","observedAt","originalTextChars","statusCode");if(!d.getString("url").equals(input.getString("url")))throw new IllegalArgumentException("Fetched source differs from planned URL");url(d.getString("finalUrl"));if(d.getString("title").length()>300||d.getString("text").length()>12000||d.getJSONArray("images").length()>12)throw new IllegalArgumentException("Source exceeds declared bounds");for(Object raw:d.getJSONArray("images")){var image=(JSONObject)raw;SpatialScene.keys(image,"url","alt");url(image.getString("url"));if(image.getString("alt").length()>200)throw new IllegalArgumentException("Image label too long");}d.put("textSha256",MeasurementStore.hash(d.getString("text")));var ref=cache(d);step.put("document",ref);if(input.getBoolean("ok")&&(d.getInt("statusCode")<200||d.getInt("statusCode")>=300||d.getString("text").length()<80))throw new IllegalArgumentException("Successful work needs an actual successful response and bounded readable text");if(phase.equals("source")&&input.getBoolean("ok"))j.getJSONArray("sources").put(ref);}
            if(phase.equals("search")&&input.getBoolean("ok")){var links=input.getJSONArray("links");if(links.isEmpty()||links.length()>12)throw new IllegalArgumentException("Actual search needs1..12 returned links");var seen=new HashSet<String>();for(Object raw:links){var link=(JSONObject)raw;SpatialScene.keys(link,"url","title");String u=url(link.getString("url"));if(j.getString("sourceKind").equals("web")&&loopback(u))continue;if(link.getString("title").length()>200)throw new IllegalArgumentException("Reference title too long");if(seen.add(u)&&j.getJSONArray("pagePlan").length()<3)j.getJSONArray("pagePlan").put(u);}step.put("links",links);}
            j.getJSONArray("steps").put(step);j.put(counter,index+1);return jobSummary(j);
        });
    }
    JSONObject finish(JSONObject input)throws Exception{return access(true,s->{var j=find(s.getJSONArray("jobs"),input.getString("id"));own(j,input);if(j.getInt("pageAttempts")<j.getJSONArray("pagePlan").length()||j.getJSONArray("pagePlan").isEmpty()&&j.getInt("searchAttempts")<j.getJSONArray("searchPlan").length())throw new IllegalStateException("Research still has planned work");for(Object raw:j.getJSONArray("sources"))source(((JSONObject)raw).getString("sha256"));boolean success=!j.getJSONArray("sources").isEmpty();var object=find(s.getJSONArray("objects"),j.getString("objectId"));boolean stale=object.getInt("identityRevision")!=j.getInt("identityRevision");j.put("status",success?(stale?"completed-stale":"completed"):"failed").put("completedAt",Instant.now()).put("reason",success?(stale?"Evidence retained for older human category; current identity changed":"Actual cached web references retained as candidate knowledge; visual match and physical properties unverified"):"No usable source pages; blocked/failed attempts retained");j.remove("lease");return jobSummary(j);});}
    JSONObject interrupt(JSONObject input)throws Exception{return access(true,s->{var j=find(s.getJSONArray("jobs"),input.getString("id"));own(j,input);j.put("status","interrupted").put("generation",j.getInt("generation")+1).put("reason","Browser worker interrupted; source receipts retained");j.remove("lease");return jobSummary(j);});}
    JSONObject control(String id,String action)throws Exception{return access(true,s->{var j=find(s.getJSONArray("jobs"),id);switch(action){case "cancel"->{if(!Set.of("queued","running","interrupted").contains(j.getString("status")))throw new IllegalStateException("Research already settled");j.put("status","cancelled").put("reason","Explicit cancellation; sources and failed attempts retained").put("generation",j.getInt("generation")+1);j.remove("lease");}case "resume"->{if(!j.getString("status").equals("interrupted"))throw new IllegalStateException("Resume only an interrupted research job");if(j.getInt("attempts")>=3)throw new IllegalStateException("Three-attempt budget reached");for(Object raw:j.getJSONArray("sources"))source(((JSONObject)raw).getString("sha256"));j.put("status","queued").put("reason","Resume queued from completed source receipts");}default->throw new IllegalArgumentException("Unknown research control");}return jobSummary(j);});}
    JSONObject evidence(String id)throws Exception{var job=job(id);var docs=new JSONArray();for(Object raw:job.getJSONArray("sources"))docs.put(source(((JSONObject)raw).getString("sha256")));return new JSONObject().put("object",object(job.getString("objectId"))).put("job",job).put("documents",docs).put("scope","Human object association plus actual cached source observations. Web text and image URLs are untrusted references; no automatic image matching, material measurement, reconstruction, weight training or native state update.");}
}
